content.content:
1	// 隔离世界：① 注入 inject.js；② 转发接口响应(带当前店名)；③ 读流量待关注 chip；
2	// ④ 接收后台指令自动切店(轮巡用)。
3	(function () {
4	  const LOG = (...a) => { try { console.log('[TemuMon]', ...a); } catch (e) {} };
5	  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
6	
7	  // 注入 MAIN world hook
8	  try {
9	    const s = document.createElement('script');
10	    s.src = chrome.runtime.getURL('inject.js');
11	    s.onload = () => s.remove();
12	    (document.head || document.documentElement).appendChild(s);
13	  } catch (e) { /* ignore */ }
14	
15	  // ---------- 读当前店铺名（右上角英文店名） ----------
16	  function findStoreNameEl() {
17	    const W = window.innerWidth;
18	    let best = null;
19	    for (const el of document.querySelectorAll('span,a,div,button,p')) {
20	      const t = (el.textContent || '').trim();
21	      if (!/^[A-Za-z][A-Za-z0-9]*(?:\s[A-Za-z0-9]+){0,3}$/.test(t)) continue;
22	      if (t.length < 2 || t.length > 30) continue;
23	      if (/^(Seller Central|Beta|NEW|SKC|SKU|USD|Best Seller)$/i.test(t)) continue;
24	      if (el.children.length > 2) continue;
25	      const r = el.getBoundingClientRect();
26	      if (r.width === 0 || r.top < 0 || r.top > 90) continue;
27	      if (r.left < W * 0.5) continue;
28	      if (!best || r.left > best.left) best = { el, left: r.left };
29	    }
30	    return best ? best.el : null;
31	  }
32	  function readStoreName() { const el = findStoreNameEl(); return el ? (el.textContent || '').trim() : null; }
33	
34	  // ---------- 转发接口响应 ----------
35	  window.addEventListener('message', (e) => {
36	    if (e.source !== window) return;
37	    const d = e.data;
38	    if (!d || d.__temuMon !== true) return;
39	    try { chrome.runtime.sendMessage({ type: 'capture', kind: d.kind, url: d.url, body: d.body, store: readStoreName() }); } catch (err) {}
40	  });
41	
42	  // ---------- 读流量待关注 chip ----------
43	  function readTrafficWatch() {
44	    const nodes = [];
45	    for (const el of document.querySelectorAll('*')) {
46	      const t = el.textContent || '';
47	      if (/商品流量待关注/.test(t) && t.length < 30) nodes.push(el);
48	    }
49	    nodes.sort((a, b) => (a.textContent || '').length - (b.textContent || '').length);
50	    for (const el of nodes) {
51	      for (const cand of [el, el.parentElement, el.parentElement && el.parentElement.parentElement]) {
52	        if (!cand) continue;
53	        const m = (cand.textContent || '').match(/商品流量待关注\s*([\d,]+)/);
54	        if (m) return Number(m[1].replace(/,/g, ''));
55	      }
56	    }
57	    return null;
58	  }
59	  let tries = 0;
60	  const iv = setInterval(() => {
61	    tries++;
62	    const n = readTrafficWatch();
63	    if (n != null) {
64	      try { chrome.runtime.sendMessage({ type: 'chipStats', trafficWatch: n, store: readStoreName() }); } catch (e) {}
65	      clearInterval(iv);
66	    } else if (tries > 20) clearInterval(iv);
67	  }, 2000);
68	
69	  // ---------- 切店自动化（轮巡用，由后台指令驱动） ----------
70	  async function waitFor(fn, timeout, step) {
71	    const t0 = Date.now();
72	    for (;;) { let r; try { r = fn(); } catch (e) { r = null; } if (r) return r; if (Date.now() - t0 > (timeout || 6000)) return null; await sleep(step || 200); }
73	  }
74	  function textEls(re, maxLen) {
75	    return [...document.querySelectorAll('*')].filter((e) => { const t = (e.textContent || '').trim(); return re.test(t) && t.length <= (maxLen || 40); });
76	  }
77	  function innermost(els) { return els.slice().sort((a, b) => (a.textContent || '').length - (b.textContent || '').length)[0] || null; }
78	  function clickableAncestor(el) { let n = el; for (let i = 0; i < 5 && n; i++) { if (n.tagName === 'BUTTON' || n.tagName === 'A' || n.getAttribute('role') === 'button') return n; n = n.parentElement; } return el; }
79	  // 完整鼠标事件序列（很多组件要 mousedown/up 才触发，单纯 click 不生效）
80	  function realClick(el) {
81	    if (!el) return false;
82	    const opts = { bubbles: true, cancelable: true, view: window };
83	    try { el.scrollIntoView({ block: 'center' }); } catch (e) {}
84	    for (const type of ['pointerdown', 'mousedown', 'mouseup', 'click']) {
85	      try { el.dispatchEvent(new MouseEvent(type, opts)); } catch (e) {}
86	    }
87	    try { el.click(); } catch (e) {}
88	    return true;
89	  }
90	  function modalOpen() { return textEls(/切换店铺|您的账户存在/, 20).length > 0; }
91	  function closeModal() {
92	    const x = document.querySelector('[aria-label="Close"],[aria-label="关闭"],.beast-core-modal-close,.semi-modal-close,.SnowModal_closeIcon');
93	    if (x) { realClick(x); return; }
94	    document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', keyCode: 27, bubbles: true }));
95	  }
96	
97	  // 压缩输出某元素的 HTML 骨架（去 style/data 属性），便于回传诊断
98	  function domSkel(el, maxLen) {
99	    if (!el) return 'null';
100	    let h = (el.outerHTML || '');
101	    h = h.replace(/\s(style|data-[\w-]+|aria-[\w-]+)="[^"]*"/g, '').replace(/>\s+</g, '><').replace(/\s{2,}/g, ' ');
102	    return h.slice(0, maxLen || 2200);
103	  }
104	
105	  function visible(el) { const b = el.getBoundingClientRect(); return b.width > 0 && b.height > 0; }
