// 探针：dump「快速筛选」区域里「商品流量待关注 / 近期有下降」chip 的真实 DOM，
// 定位插件被动读数为何得到 0。产物写 data/probe-flow.json。
import { writeFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { loadConfig, ROOT } from './src/config.js';
import { launchBrowser, gotoWithRetry, waitForGoodsList } from './src/browser.js';
import { closePopups } from './src/popups.js';

const cfg = loadConfig();
const { context, page } = await launchBrowser(cfg, { headless: true });

await gotoWithRetry(page, cfg.goodsListUrl, cfg);
await waitForGoodsList(page, { timeout: cfg.navTimeoutMs });
await closePopups(page).catch(() => {});
await page.waitForTimeout(4000);

const dump = await page.evaluate(() => {
  const skel = (el, max) => {
    if (!el) return null;
    let h = el.outerHTML || '';
    h = h.replace(/\s(style|data-[\w-]+|aria-[\w-]+)="[^"]*"/g, '').replace(/>\s+</g, '><').replace(/\s{2,}/g, ' ');
    return h.slice(0, max || 1200);
  };
  const out = { watchChips: [], declineHits: [], totalText: null };

  // 所有含「商品流量待关注」的最小元素 → 记录自身/父/祖父的文本与骨架
  const all = [...document.querySelectorAll('*')];
  const watchEls = all.filter((e) => /商品流量待关注/.test(e.textContent || '') && (e.textContent || '').length < 40);
  watchEls.sort((a, b) => (a.textContent || '').length - (b.textContent || '').length);
  for (const el of watchEls.slice(0, 3)) {
    const chain = [];
    let n = el;
    for (let i = 0; i < 3 && n; i++, n = n.parentElement) {
      chain.push({ tag: n.tagName, cls: String(n.className || '').slice(0, 40), text: (n.textContent || '').trim().slice(0, 50), skel: i === 1 ? skel(n, 900) : undefined });
    }
    out.watchChips.push(chain);
  }

  // 「商品流量近期有下降」/「批量处理流量下降商品」是否存在
  out.declineHits = all
    .filter((e) => /流量.*下降|批量处理流量下降/.test(e.textContent || '') && (e.textContent || '').length < 40)
    .slice(0, 4)
    .map((e) => ({ tag: e.tagName, text: (e.textContent || '').trim().slice(0, 40) }));

  // 「共有 N 条」
  const tot = all.find((x) => x.children.length === 0 && /共有\s*[\d,]+\s*条/.test(x.textContent || ''));
  out.totalText = tot ? tot.textContent.trim() : null;
  return out;
});

writeFileSync(resolve(ROOT, 'data', 'probe-flow.json'), JSON.stringify(dump, null, 2), 'utf8');
console.log(JSON.stringify(dump, null, 2));
await context.close();
process.exit(0);

