  const watchEls = all.filter((e) => /商品流量待关注/.test(e.textContent || '') && (e.textContent || '').length < 40);
  watchEls.sort((a, b) => (a.textContent || '').length - (b.textContent || '').length);
  for (const el of watchEls.slice(0, 3)) {
    const chain = [];
    let n = el;
    for (let i = 0; i < 3 && n; i++, n = n.parentElement) {
      chain.push({ tag: n.tagName, cls: String(n.className || '').slice(0, 40), text: (n.textContent || '').trim().slice(0, 50), skel: i === 1 ? skel(n, 900) : undefined });
    }
    out.watchChips.push(chain);
  }

  // 「商品流量近期有下降」/「批量处理流量下降商品」是否存在
  out.declineHits = all
    .filter((e) => /流量.*下降|批量处理流量下降/.test(e.textContent || '') && (e.textContent || '').length < 40)
    .slice(0, 4)
    .map((e) => ({ tag: e.tagName, text: (e.textContent || '').trim().slice(0, 40) }));

  // 「共有 N 条」
  const tot = all.find((x) => x.children.length === 0 && /共有\s*[\d,]+\s*条/.test(x.textContent || ''));
  out.totalText = tot ? tot.textContent.trim() : null;
  return out;
});

